 final android.app.Instrumentation inst=InstrumentationRegistry.getInstrumentation();final Context c=inst.getTargetContext();MainActivity activity;
 @Before public void setup(){AudioSettings.init(c);for(String k:List.of("perfect","sox","eq","limiter"))AudioSettings.put(k,false);for(String k:List.of("preamp","crossfeed","balance","dynamicBass"))AudioSettings.put(k,0);AudioSettings.put("volumeCeiling",100);AudioSettings.put("replayGain","off");AudioSettings.put("mode","android");AudioSettings.put("bits",0);AudioSettings.put("rate",0);c.getSharedPreferences("aura",0).edit().putBoolean("widePlayerFullscreen",false).putBoolean("scanOnLaunch",false).putString("appearance",InstrumentationRegistry.getArguments().getString("theme","dark")).commit();MusicCollections.prefs(c).edit().clear().commit();ReplayGain.reset();}
 @After public void cleanup()throws Exception{if(activity!=null)main(()->{var p=player();if(p!=null){p.stop();p.clearMediaItems();}activity.finish();return null;});AudioSettings.put("dynamicBass",0);AudioSettings.put("replayGain","off");AudioSettings.put("volumeCeiling",100);AudioSettings.put("perfect",false);}
 Track track(String uri,String title){return new Track(uri,title,"AURA Sessions","Quiet Tides","Music",3000,"").withGenre("Ambient");}
 @Test public void backupRelinksOnlyUniqueSongIdentitiesAfterFolderChanges()throws Exception{Track old=track("file:///old-folder/song.wav","Relink Song"),fresh=track("file:///new-folder/song.wav","Relink Song");String from=MusicCollections.key(old.uri),to=MusicCollections.key(fresh.uri);MusicCollections.favorite(c,old.uri,true);MusicCollections.prefs(c).edit().putString("pending-links",new JSONArray().put(old.json()).toString()).putString("bookmarks:"+from,"[{\"title\":\"Intro\",\"position\":1250}]").putLong("lyric-offset:"+from,150).commit();c.getSharedPreferences("aura",0).edit().putString("playlists",new JSONObject().put("Ocean",new JSONArray().put(old.uri)).toString()).commit();BackupLinks.apply(c,List.of(fresh));assertTrue("favorite remapped",MusicCollections.favorite(c,fresh.uri));assertFalse(MusicCollections.favorite(c,old.uri));assertEquals(150,MusicCollections.prefs(c).getLong("lyric-offset:"+to,0));assertTrue(MusicCollections.prefs(c).getString("bookmarks:"+to,"").contains("1250"));assertEquals(fresh.uri,new JSONObject(c.getSharedPreferences("aura",0).getString("playlists","{}")).getJSONArray("Ocean").getString(0));}
 @Test public void backupRejectsWrongPreferenceTypesBeforeWriting()throws Exception{JSONObject b=ListeningBackup.export(c);b.getJSONObject("preferences").getJSONObject("music").put("favorites",new JSONObject().put("type","string").put("value","wrong"));try{ListeningBackup.restore(c,new ByteArrayInputStream(b.toString().getBytes()));fail();}catch(IOException expected){}assertTrue(MusicCollections.prefs(c).getStringSet("favorites",Set.of()).isEmpty());}
 @Test public void widgetUsesNativeRemoteViewsAndControlsLivePlayback()throws Exception{launch();File tone=new File(c.getCacheDir(),"widget-tone.wav");try(var in=inst.getContext().getAssets().open("tone.wav");var out=new FileOutputStream(tone)){out.write(Io.read(in));}Track t=track(Uri.fromFile(tone).toString(),"Widget Song");main(()->{player().setMediaItem(t.item());player().setRepeatMode(androidx.media3.common.Player.REPEAT_MODE_ONE);player().prepare();player().play();return null;});await(()->main(()->player().isPlaying()),7000);main(()->{assertEquals("Widget Song",activity.musicCurrent().title);View view=MusicWidget.views(c,t.title,t.artist,t.uri,true).apply(c.getApplicationContext(),null);assertNotNull(find(view,"Widget Song"));c.sendBroadcast(new Intent(c,MusicWidget.class).setAction("dev.aura.player.widget.toggle"));return null;});await(()->main(()->!player().isPlaying()),7000);main(()->{activity.musicGo("widget");return null;});Thread.sleep(450);capture("features-widget");}
 @Test public void replayGainTagsReachTheLivePlaybackPipeline()throws Exception{launch();byte[] original;try(var in=inst.getContext().getAssets().open("pcm24.flac")){original=Io.read(in);}int at=4,last=-1;while(true){int head=original[at]&255,length=((original[at+1]&255)<<16)|((original[at+2]&255)<<8)|(original[at+3]&255);last=at;at+=4+length;if((head&128)!=0)break;}original[last]=(byte)(original[last]&127);ByteArrayOutputStream comments=new ByteArrayOutputStream();java.util.function.IntConsumer le=n->{comments.write(n&255);comments.write((n>>8)&255);comments.write((n>>16)&255);comments.write((n>>24)&255);};byte[] vendor="AURA test".getBytes();le.accept(vendor.length);comments.write(vendor);le.accept(2);for(String tag:List.of("REPLAYGAIN_TRACK_GAIN=-6.00 dB","REPLAYGAIN_TRACK_PEAK=1.0")){byte[] bytes=tag.getBytes();le.accept(bytes.length);comments.write(bytes);}byte[] payload=comments.toByteArray();File f=new File(c.getCacheDir(),"gain-live.flac");try(var out=new FileOutputStream(f)){out.write(original,0,at);out.write(0x84);out.write((payload.length>>16)&255);out.write((payload.length>>8)&255);out.write(payload.length&255);out.write(payload);out.write(original,at,original.length-at);}AudioSettings.put("replayGain","track");main(()->{player().setMediaItem(new androidx.media3.common.MediaItem.Builder().setUri(Uri.fromFile(f)).build());player().setRepeatMode(androidx.media3.common.Player.REPEAT_MODE_ONE);player().prepare();player().play();return null;});await(()->ReplayGain.gainDb< -5.9,8000);assertEquals(-6,ReplayGain.gainDb,.01);await(()->main(()->player().isPlaying())&&PcmSink.signal!=null,8000);Thread.sleep(3500);assertEquals(-6,ReplayGain.gainDb,.01);}
 @Test public void serviceTimerStopsAndABLoopRepeatsInBackground()throws Exception{launch();File f=new File(c.getCacheDir(),"tools-live.wav");try(var in=inst.getContext().getAssets().open("tone.wav");var out=new FileOutputStream(f)){out.write(Io.read(in));}main(()->{player().setMediaItem(androidx.media3.common.MediaItem.fromUri(Uri.fromFile(f)));player().setRepeatMode(androidx.media3.common.Player.REPEAT_MODE_ONE);player().prepare();player().play();return null;});await(()->main(()->player().getCurrentPosition()>200),8000);main(()->{PlaybackTools.instance.player.seekTo(500);PlaybackTools.instance.pointA();PlaybackTools.instance.player.seekTo(1500);assertTrue(PlaybackTools.instance.pointB());PlaybackTools.instance.player.seekTo(1550);return null;});await(()->main(()->player().getCurrentPosition()<1200),2000);main(()->{PlaybackTools.instance.clearLoop();PlaybackTools.instance.deadline=android.os.SystemClock.elapsedRealtime()+150;activity.moveTaskToBack(true);return null;});await(()->main(()->!player().isPlaying()),2500);assertEquals(0,PlaybackTools.instance.deadline);}
 @Test public void foldLayoutsKeepTheSamePlaybackAndCapture()throws Exception{org.junit.Assume.assumeTrue(c.getResources().getConfiguration().screenWidthDp>=700);launch();File f=new File(c.getCacheDir(),"dock-tone.wav");try(var in=inst.getContext().getAssets().open("tone.wav");var out=new FileOutputStream(f)){out.write(Io.read(in));}List<Track> songs=new ArrayList<>();for(int i=0;i<30;i++)songs.add(track(Uri.fromFile(f).buildUpon().fragment("dock"+i).build().toString(),"Coastal Light "+(i+1)));Bitmap cover=new SongInfoDesignTest().designCover();ArtworkStore.save(c,songs.get(0).uri,cover);cover.recycle();ArtworkView.clearCache();main(()->{set("tracks",songs);set("tab","곡");set("source","all");set("folderCursor","");player().setMediaItems(songs.stream().map(Track::item).collect(java.util.stream.Collectors.toList()));player().setRepeatMode(androidx.media3.common.Player.REPEAT_MODE_ONE);player().prepare();player().play();activity.musicGo("library");return null;});await(()->main(()->player().isPlaying()),8000);Thread.sleep(600);main(()->{LinearLayout mini=(LinearLayout)get("mini"),nav=(LinearLayout)get("nav");MusicBottomBar dock=(MusicBottomBar)mini.getParent();assertTrue(dock.wide);assertEquals(dock.getWidth()*5/8,nav.getWidth());assertEquals(dock.getWidth()-nav.getWidth(),mini.getWidth());assertEquals(View.VISIBLE,mini.getVisibility());assertFalse(((AdaptiveMusicPane)get("adaptivePane")).expanded);return null;});capture("features-bottom-dock");main(()->{TextView title=(TextView)get("miniTitle");((View)title.getParent()).performClick();assertTrue((boolean)get("dockOpened"));assertEquals("library",get("page"));return null;});Thread.sleep(700);main(()->{AdaptiveMusicPane pane=(AdaptiveMusicPane)get("adaptivePane");assertEquals(.375f,pane.dockFraction,.001f);assertEquals(pane.getWidth()*5/8,pane.primary.getWidth(),1);return null;});capture("features-player-panel");main(()->{activity.musicToggleDockFull();return null;});Thread.sleep(700);main(()->{assertTrue((boolean)get("dockFull"));assertEquals(View.GONE,((AdaptiveMusicPane)get("adaptivePane")).primary.getVisibility());return null;});capture("features-dock-player");File manual=new File(c.getFilesDir(),"manual-lyrics/"+MusicCollections.key(songs.get(0).uri)+".lrc");manual.getParentFile().mkdirs();java.nio.file.Files.write(manual.toPath(),"[00:00.00]A quiet tide beneath the moon\n[00:01.00]The city lights are fading slowly\n[00:02.00]We follow echoes through the blue\n[00:03.00]And let the night carry us home".getBytes());main(()->{set("lyricsKey","");activity.musicToggleDockLyrics();return null;});Thread.sleep(1000);assertTrue(main(()->((DockPlayerView)get("dockPlayer")).lines.size()>0));capture("features-player-split-lyrics");main(()->{activity.musicToggleDockLyrics();activity.musicToggleDockFull();return null;});Thread.sleep(700);assertFalse(main(()->(boolean)get("dockFull")));main(()->{activity.musicCloseDock();return null;});Thread.sleep(500);assertFalse(main(()->(boolean)get("dockOpened")));main(()->{((View)((TextView)get("miniTitle")).getParent()).performClick();return null;});Thread.sleep(500);assertFalse(main(()->(boolean)get("dockFull")));main(()->{activity.musicToggleDockFull();return null;});Thread.sleep(500);main(()->{DockPlayerView panel=(DockPlayerView)get("dockPlayer");PlayerScrollView view=panel.playerScroll;view.scrollTo(0,0);long at=android.os.SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(at,at,MotionEvent.ACTION_DOWN,80,50,0),move=MotionEvent.obtain(at,at+100,MotionEvent.ACTION_MOVE,80,320,0),up=MotionEvent.obtain(at,at+150,MotionEvent.ACTION_UP,80,350,0);view.onInterceptTouchEvent(down);assertTrue(view.onInterceptTouchEvent(move));view.onTouchEvent(move);view.onTouchEvent(up);down.recycle();move.recycle();up.recycle();return null;});Thread.sleep(700);assertFalse(main(()->(boolean)get("dockOpened")));main(()->{((View)((TextView)get("miniTitle")).getParent()).performClick();return null;});Thread.sleep(600);assertTrue(main(()->(boolean)get("dockFull")));assertTrue(main(()->player().isPlaying()));manual.delete();}

 @Test public void bottomDockUsesPhoneLayoutForTallDisplays(){assertTrue(MusicBottomBar.wide(1280,900,1));assertTrue(MusicBottomBar.wide(900,1100,1));assertFalse(MusicBottomBar.wide(900,1800,1));assertFalse(MusicBottomBar.wide(420,900,1));assertFalse(MusicBottomBar.wide(1400,3000,2));}

 @Test public void collectionsFollowActualAddedFavoritesAndListeningRules()throws Exception{Track a=track("file:///mix-a.wav","Blue Hour"),b=track("file:///mix-b.wav","Slow Waves");MusicCollections.favorite(c,b.uri,true);try(MusicCollections store=new MusicCollections(c)){long old=System.currentTimeMillis()-40L*86400000;ListeningStore.get(c).write("mix-test",a,old,1000,1);var mixes=store.mixes(c,List.of(a,b));assertTrue(mixes.stream().anyMatch(m->m.title().equals("즐겨찾는 음악")&&m.songs().equals(List.of(b))));assertTrue(mixes.stream().anyMatch(m->m.title().equals("오랜만에 듣는 곡")&&m.songs().contains(a)));assertTrue(mixes.stream().anyMatch(m->m.title().equals("아직 듣지 않은 곡")&&m.songs().contains(b)&&!m.songs().contains(a)));MusicCollections.prefs(c).edit().putString("mixes","[{\"name\":\"My Ambient\",\"genre\":\"Ambient\",\"favorite\":true}]").commit();assertEquals(List.of(b),store.mixes(c,List.of(a,b)).stream().filter(m->m.title().equals("My Ambient")).findFirst().get().songs());}ListeningStore.get(c).getWritableDatabase().delete("heard","visit=?",new String[]{"mix-test"});}
 @Test public void duplicateCandidatesRequireMatchingIdentityAndNearDuration(){Track a=track("file:///dup-a","Blue Hour"),b=track("file:///dup-b","Blue Hour"),different=track("file:///dup-c","Another Song");assertEquals(1,MusicCollections.duplicates(List.of(a,b,different)).size());MusicCollections.prefs(c).edit().putStringSet("hidden",Set.of(b.uri)).commit();assertEquals(List.of(a,different),MusicCollections.visible(c,List.of(a,b,different)));}
 @Test public void backupRoundTripKeepsDataButNeverCredentialsOrDeviceRouting()throws Exception{c.getSharedPreferences("aura",0).edit().putString("playlists","{\"Ocean\":[\"file:///song\"]}").commit();AudioSettings.put("dynamicBass",35);AudioSettings.put("device",875);MusicCollections.favorite(c,"file:///song",true);MusicCollections.prefs(c).edit().putLong("lyric-offset:test",250).commit();var backup=ListeningBackup.export(c);assertFalse(backup.toString().contains("accessToken"));assertFalse(backup.getJSONObject("preferences").getJSONObject("audio").has("device"));AudioSettings.put("dynamicBass",0);MusicCollections.prefs(c).edit().clear().commit();ListeningBackup.restore(c,new ByteArrayInputStream(backup.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertEquals(35,AudioSettings.extra.bass(),0);assertTrue(MusicCollections.favorite(c,"file:///song"));assertEquals(250,MusicCollections.prefs(c).getLong("lyric-offset:test",0));assertEquals(875,AudioSettings.current.deviceId());AudioSettings.put("device",0);}
 @Test public void invalidBackupDoesNotTouchSettings()throws Exception{AudioSettings.put("dynamicBass",31);try{ListeningBackup.restore(c,new ByteArrayInputStream("{\"format\":\"other\",\"version\":1}".getBytes()));fail();}catch(Exception expected){}assertEquals(31,AudioSettings.extra.bass(),0);}
 @Test public void replayGainReadsTrackAndAlbumAndUsesPeakLimit(){AudioSettings.put("replayGain","track");ReplayGain.read(new androidx.media3.common.Metadata(new androidx.media3.extractor.metadata.vorbis.VorbisComment("REPLAYGAIN_TRACK_GAIN","+6.0 dB"),new androidx.media3.extractor.metadata.vorbis.VorbisComment("REPLAYGAIN_TRACK_PEAK","0.8"),new androidx.media3.extractor.metadata.vorbis.VorbisComment("REPLAYGAIN_ALBUM_GAIN","-5.0 dB")));assertEquals(-20*Math.log10(.8),ReplayGain.gainDb,.001);AudioSettings.put("replayGain","album");ReplayGain.update();assertEquals(-5,ReplayGain.gainDb,.001);ReplayGain.reset();assertEquals(0,ReplayGain.gainDb,0);AudioSettings.put("perfect",true);AudioSettings.put("dynamicBass",100);assertFalse(AudioSettings.dsp(AudioSettings.current));}
 @Test public void dynamicBassReinforcesLowFrequenciesAndDoesNotOverflow(){double low=response(60,.01,70),high=response(5000,.01,70);assertTrue("Bass gain should exceed high frequency gain",low>high*1.8);double peak=response(60,.95,100);assertTrue(Double.isFinite(peak)&&peak<=.971);}
 double response(int frequency,double amplitude,int amount){DynamicBass bass=new DynamicBass(2);bass.configure(amount,90,44100);double[] samples=new double[2];double peak=0;for(int i=0;i<44100;i++){samples[0]=samples[1]=amplitude*Math.sin(2*Math.PI*frequency*i/44100);bass.frame(samples,2);if(i>22050)peak=Math.max(peak,Math.abs(samples[0]));}return peak;}
 @Test public void offlineDownloadIsAtomicAndSeekableWithoutGoogleAccount()throws Exception{Track t=track(DriveUris.file("offline-test","song","Tone.wav").toString(),"Offline Tone");OfflineMusic.remove(c,t.uri);try(DriveTest.FakeDrive server=new DriveTest.FakeDrive(200044)){DriveHttp http=new DriveHttp(server.base(),new DriveHttp.Tokens(){public String token(){return "fake";}public void invalidate(String x){}});try(DriveDataSource source=new DriveDataSource(http,u->true)){OfflineMusic.download(c,t,source,n->{});}assertNotNull(OfflineMusic.available(c,t.uri));DriveAuth.get(c).clear();try(DsdDataSource source=new DsdDataSource(c)){assertEquals(20,source.open(new androidx.media3.datasource.DataSpec.Builder().setUri(t.uri).setPosition(100).setLength(20).build()));byte[] b=new byte[20];assertEquals(20,source.read(b,0,20));assertEquals(server.audio(100),b[0]);}assertEquals(1,OfflineMusic.tracks(c).size());}finally{OfflineMusic.remove(c,t.uri);}}
 @Test public void cancelledOfflineDownloadNeverPublishesPartialFile()throws Exception{Track t=track(DriveUris.file("offline-test","cancel","Tone.wav").toString(),"Cancel");OfflineMusic.remove(c,t.uri);try(DriveTest.FakeDrive server=new DriveTest.FakeDrive(200044)){DriveHttp http=new DriveHttp(server.base(),new DriveHttp.Tokens(){public String token(){return "fake";}public void invalidate(String x){}});try(DriveDataSource source=new DriveDataSource(http,u->true)){try{OfflineMusic.download(c,t,source,n->{throw new CancellationException();});fail();}catch(CancellationException expected){}}assertNull(OfflineMusic.available(c,t.uri));assertFalse(new File(OfflineMusic.file(c,t.uri)+".partial").exists());}}
